protocol Loggable { func log() -> String }

extension Loggable where Self: Entity {
  func log() -> String { "[\(Self.self) \(id)]" }
}

// Compose behaviour on a struct — no class needed
struct Order: Entity, Persistable, Loggable {
  let id: String
  func save() throws { /* ... */ }
}

let o = Order(id: "42")
print(o.log()) // [Order 42] — from the default implementation

