// POP boundary for testing
protocol AnalyticsClient { func track(_ event: String) }

struct ProdAnalytics: AnalyticsClient { func track(_ e: String) {} }

// A fake needs to record — so it needs reference semantics, not `mutating`.
// A `mutating func` cannot satisfy a non-mutating protocol requirement.
final class FakeAnalytics: AnalyticsClient {
  private(set) var events: [String] = []
  func track(_ e: String) { events.append(e) }
}

struct ViewModel { let analytics: any AnalyticsClient }

