// Custom: identity is the id alone, so hashing must agree
struct User: Hashable, Comparable, Identifiable {
  let id: UUID
  var name: String
  var lastSeen: Date

  static func == (a: User, b: User) -> Bool { a.id == b.id }
  func hash(into hasher: inout Hasher) { hasher.combine(id) }   // id only
  static func < (a: User, b: User) -> Bool { a.name < b.name }  // sorting
}

let users = [User(id: UUID(), name: "Bo", lastSeen: .now)]
_ = users.sorted()                    // free from Comparable
var byUser: [User: Int] = [:]         // free from Hashable

// ❌ Broken contract: equal values that hash differently
struct Broken: Hashable {
  let id: Int
  var cachedName: String
  static func == (a: Broken, b: Broken) -> Bool { a.id == b.id }
  func hash(into h: inout Hasher) { h.combine(cachedName) }  // ignored by ==
}

// Classes: nothing is synthesized, and identity is a separate question
final class Session: Equatable {
  let token: String
  init(token: String) { self.token = token }
  static func == (a: Session, b: Session) -> Bool { a.token == b.token }
}
let s1 = Session(token: "x"), s2 = Session(token: "x")
print(s1 == s2, s1 === s2)            // true false

@MainActor
protocol UploaderDelegate: AnyObject {          // ✅ class-bound, so weak is legal
  func uploader(_ uploader: Uploader, didProgress fraction: Double)
  func uploader(_ uploader: Uploader, didFinish url: URL)
  func uploader(_ uploader: Uploader, didFail error: Error)
}

extension UploaderDelegate {                    // Swift-native "optional" methods
  func uploader(_ uploader: Uploader, didProgress fraction: Double) {}
}

final class Uploader {
  weak var delegate: UploaderDelegate?          // ✅ no retain cycle

  func run(_ file: URL) async {
    do {
      let remote = try await api.upload(file)
      delegate?.uploader(self, didFinish: remote)
    } catch {
      delegate?.uploader(self, didFail: error)
    }
  }
}

final class UploadScreen: UIViewController, UploaderDelegate {
  private let uploader = Uploader()             // screen owns the uploader

  override func viewDidLoad() {
    super.viewDidLoad()
    uploader.delegate = self                    // uploader points back weakly
  }

  func uploader(_ uploader: Uploader, didFinish url: URL) { dismiss(animated: true) }
  func uploader(_ uploader: Uploader, didFail error: Error) { show(error) }
}

// ❌ var delegate: UploaderDelegate?   — strong: both objects leak
// ❌ protocol UploaderDelegate { }     — not class-bound: 'weak' will not compile

