}
downloader.onFinish = { [weak self] url in self?.show(url) }

protocol Greeter {
  func greet() -> String        // ✅ a requirement — dynamically dispatched
}

extension Greeter {
  func greet() -> String { "hello from the default" }
  func shout() -> String { "SHOUT from the extension" }   // ⚠️ not a requirement
}

struct Robot: Greeter {
  func greet() -> String { "beep" }
  func shout() -> String { "BEEP" }
}

let robot = Robot()
let asProtocol: any Greeter = robot

print(robot.greet())        // "beep"
print(asProtocol.greet())   // "beep"  — witness table, the type wins

print(robot.shout())        // "BEEP"
print(asProtocol.shout())   // "SHOUT from the extension"  — static dispatch

// Generics behave like the protocol case for requirements
func announce<G: Greeter>(_ g: G) {
  print(g.greet())          // "beep"
  print(g.shout())          // "SHOUT from the extension"
}

