class Formatter {
  static let shared = Formatter()          // lazily initialized once, thread-safe

  static func staticName() -> String { "Formatter" }   // cannot be overridden
  class func kind() -> String { "generic" }            // subclasses may override

  // class var stored = 0                  // ❌ stored type properties must be static
  static var registry: [String] = []       // ❌ under Swift 6: global mutable state
}

final class CurrencyFormatter: Formatter {
  override class func kind() -> String { "currency" }
  // override static func staticName() -> String  // ❌ cannot override a static member
}

print(Formatter.kind(), CurrencyFormatter.kind())   // generic currency

